solid.code:
import { Component, JSX, splitProps } from 'solid-js';

export interface AnimatedSphereProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const AnimatedSphere: Component<AnimatedSphereProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <div
      class={`relative flex items-center justify-center overflow-hidden rounded-2xl bg-card border border-border p-4 shadow-sm ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </div>
  );
};

